import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer st = new StringTokenizer("");

    static String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) throw new IOException("EOF");
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }

    @SuppressWarnings("unchecked")
    public static void main(String[] args) throws IOException {
        int L = Integer.parseInt(next());
        int C = Integer.parseInt(next());
        final int MAXV = 26 * 26;

        boolean[] present = new boolean[MAXV];
        boolean[] solved = new boolean[MAXV];
        long[] val = new long[MAXV];

        HashMap<Integer, Integer>[] rowMap = new HashMap[L];
        HashMap<Integer, Integer>[] colMap = new HashMap[C];
        long[] rowSum = new long[L];
        long[] colSum = new long[C];
        for (int i = 0; i < L; i++) rowMap[i] = new HashMap<>();
        for (int j = 0; j < C; j++) colMap[j] = new HashMap<>();

        ArrayList<Integer>[] varRows = new ArrayList[MAXV];
        ArrayList<Integer>[] varCols = new ArrayList[MAXV];
        for (int i = 0; i < MAXV; i++) {
            varRows[i] = new ArrayList<>();
            varCols[i] = new ArrayList<>();
        }

        for (int r = 0; r < L; r++) {
            for (int c = 0; c < C; c++) {
                String name = next();
                int id = (name.charAt(0) - 'a') * 26 + (name.charAt(1) - 'a');
                present[id] = true;
                Integer cur = rowMap[r].get(id);
                rowMap[r].put(id, cur == null ? 1 : cur + 1);
                cur = colMap[c].get(id);
                colMap[c].put(id, cur == null ? 1 : cur + 1);
                varRows[id].add(r);
                varCols[id].add(c);
            }
            rowSum[r] = Long.parseLong(next());
        }
        for (int c = 0; c < C; c++) colSum[c] = Long.parseLong(next());

        ArrayList<Integer> queue = new ArrayList<>();
        int head = 0;
        for (int r = 0; r < L; r++) if (rowMap[r].size() == 1) queue.add(r);
        for (int c = 0; c < C; c++) if (colMap[c].size() == 1) queue.add(L + c);

        while (head < queue.size()) {
            int p = queue.get(head++);
            HashMap<Integer, Integer> m;
            long sum;
            int off;
            if (p < L) {
                m = rowMap[p];
                sum = rowSum[p];
                off = 0;
            } else {
                m = colMap[p - L];
                sum = colSum[p - L];
                off = L;
            }
            if (m.size() != 1) continue;
            Map.Entry<Integer, Integer> e = m.entrySet().iterator().next();
            int id = e.getKey();
            if (solved[id]) continue;

            long x = sum / e.getValue();
            val[id] = x;
            solved[id] = true;

            // remove a variável resolvida de todas as linhas / colunas
            for (int idx : varRows[id]) {
                HashMap<Integer, Integer> mm = rowMap[idx];
                Integer cnt = mm.get(id);
                if (cnt != null) {
                    rowSum[idx] -= x * cnt;
                    mm.remove(id);
                    if (mm.size() == 1) queue.add(idx);
                }
            }
            for (int idx : varCols[id]) {
                HashMap<Integer, Integer> mm = colMap[idx];
                Integer cnt = mm.get(id);
                if (cnt != null) {
                    colSum[idx] -= x * cnt;
                    mm.remove(id);
                    if (mm.size() == 1) queue.add(L + idx);
                }
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int id = 0; id < MAXV; id++) {
            if (present[id]) {
                char a = (char) ('a' + id / 26);
                char b = (char) ('a' + id % 26);
                sb.append(a).append(b).append(' ').append(val[id]).append('\n');
            }
        }
        System.out.print(sb);
    }
}
